using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestDbContextFactory.CreateSeeded();
            _controller = new InstructorsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_NoParams_ReturnsViewWithInstructors()
        {
            var result = _controller.Index(null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.Equal(2, model.Instructors.Count());
        }

        [Fact]
        public void Index_WithInstructorId_ShowsCourses()
        {
            var instructor = _context.Instructors.First();

            var result = _controller.Index(instructor.ID, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(model.Courses);
            Assert.NotEmpty(model.Courses);
        }

        [Fact]
        public void Index_WithInstructorAndCourseId_ShowsEnrollments()
        {
            var instructor = _context.Instructors.First();
            var courseAssignment = _context.CourseAssignments.First(ca => ca.InstructorID == instructor.ID);
            var courseId = courseAssignment.CourseID;

            var result = _controller.Index(instructor.ID, courseId) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<InstructorIndexData>(result.Model);
            Assert.NotNull(model.Enrollments);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithInstructor()
        {
            var instructor = _context.Instructors.First();

            var result = _controller.Details(instructor.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal(instructor.ID, model.ID);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null) as StatusCodeResult;

            Assert.NotNull(result);
            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Details_InvalidId_ReturnsNotFound()
        {
            var result = _controller.Details(99999) as NotFoundResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Create_Get_ReturnsViewWithAssignedCourseData()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.NotNull(model.CourseAssignments);
            Assert.NotNull(_controller.ViewBag.Courses);
        }

        [Fact]
        public void Create_Post_ValidInstructor_RedirectsToIndex()
        {
            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = DateTime.Parse("2023-01-15"),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, null!) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.True(_context.Instructors.Any(i => i.LastName == "Instructor"));
        }

        [Fact]
        public void Create_Post_WithSelectedCourses_AddsCourseAssignments()
        {
            var course = _context.Courses.First();
            var instructor = new Instructor
            {
                FirstMidName = "Course",
                LastName = "Assigner",
                HireDate = DateTime.Parse("2023-01-15"),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, new[] { course.CourseID.ToString() }) as RedirectToActionResult;

            Assert.NotNull(result);
            var saved = _context.Instructors.First(i => i.LastName == "Assigner");
            var assignments = _context.CourseAssignments.Where(ca => ca.InstructorID == saved.ID).ToList();
            Assert.Single(assignments);
            Assert.Equal(course.CourseID, assignments[0].CourseID);
        }

        [Fact]
        public void Create_Post_InvalidModel_ReturnsView()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "",
                HireDate = DateTime.Today,
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = _controller.Create(instructor, null!) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithInstructor()
        {
            var instructor = _context.Instructors.First();

            var result = _controller.Delete(instructor.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Instructor>(result.Model);
            Assert.Equal(instructor.ID, model.ID);
        }

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null) as StatusCodeResult;

            Assert.NotNull(result);
            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Delete_Get_InvalidId_ReturnsNotFound()
        {
            var result = _controller.Delete(99999) as NotFoundResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void DeleteConfirmed_RemovesInstructorAndNullifiesDepartment()
        {
            var instructor = _context.Instructors.First();
            var instructorId = instructor.ID;
            // Ensure this instructor is an admin of a department
            var dept = _context.Departments.FirstOrDefault(d => d.InstructorID == instructorId);

            var result = _controller.DeleteConfirmed(instructorId) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Null(_context.Instructors.Find(instructorId));

            if (dept != null)
            {
                var updatedDept = _context.Departments.Find(dept.DepartmentID);
                Assert.Null(updatedDept!.InstructorID);
            }
        }

        [Fact]
        public void Index_SetsViewBagInstructorID()
        {
            var instructor = _context.Instructors.First();

            _controller.Index(instructor.ID, null);

            Assert.Equal(instructor.ID, _controller.ViewBag.InstructorID);
        }

        [Fact]
        public void Index_SetsCourseIDInViewBag()
        {
            var instructor = _context.Instructors.First();
            var assignment = _context.CourseAssignments.First(ca => ca.InstructorID == instructor.ID);

            _controller.Index(instructor.ID, assignment.CourseID);

            Assert.Equal(assignment.CourseID, _controller.ViewBag.CourseID);
        }
    }
}

