using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests : IDisposable
    {
        private readonly SchoolContext _context;

        public SchoolContextTests()
        {
            _context = TestDbContextFactory.Create();
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        [Fact]
        public void SchoolContext_HasAllDbSets()
        {
            Assert.NotNull(_context.Courses);
            Assert.NotNull(_context.Enrollments);
            Assert.NotNull(_context.Departments);
            Assert.NotNull(_context.OfficeAssignments);
            Assert.NotNull(_context.CourseAssignments);
            Assert.NotNull(_context.People);
            Assert.NotNull(_context.Students);
            Assert.NotNull(_context.Instructors);
            Assert.NotNull(_context.Notifications);
        }

        [Fact]
        public void CourseAssignment_HasCompositeKey()
        {
            var entityType = _context.Model.FindEntityType(typeof(CourseAssignment));

            Assert.NotNull(entityType);
            var key = entityType!.FindPrimaryKey();
            Assert.NotNull(key);
            var keyProperties = key!.Properties.Select(p => p.Name).ToList();
            Assert.Contains("CourseID", keyProperties);
            Assert.Contains("InstructorID", keyProperties);
        }

        [Fact]
        public void Student_InheritsFromPerson_WithTPH()
        {
            var personEntityType = _context.Model.FindEntityType(typeof(Person));
            Assert.NotNull(personEntityType);

            // Both Student and Instructor share the Person table
            var studentEntityType = _context.Model.FindEntityType(typeof(Student));
            Assert.NotNull(studentEntityType);
        }

        [Fact]
        public void CanAddAndQueryStudent()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2023-09-01")
            };

            _context.Students.Add(student);
            _context.SaveChanges();

            var retrieved = _context.Students.First(s => s.LastName == "Student");
            Assert.Equal("Test", retrieved.FirstMidName);
        }

        [Fact]
        public void CanAddAndQueryCourse()
        {
            var dept = new Department
            {
                Name = "Test Dept",
                Budget = 100000,
                StartDate = DateTime.Parse("2023-01-01")
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 5555,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var retrieved = _context.Courses.Find(5555);
            Assert.NotNull(retrieved);
            Assert.Equal("Test Course", retrieved!.Title);
        }

        [Fact]
        public void CanAddInstructorWithOfficeAssignment()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Office",
                LastName = "Test",
                HireDate = DateTime.Parse("2023-01-01"),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var office = new OfficeAssignment
            {
                InstructorID = instructor.ID,
                Location = "Room 101"
            };
            _context.OfficeAssignments.Add(office);
            _context.SaveChanges();

            var retrieved = _context.Instructors
                .Include(i => i.OfficeAssignment)
                .First(i => i.LastName == "Test");
            Assert.NotNull(retrieved.OfficeAssignment);
            Assert.Equal("Room 101", retrieved.OfficeAssignment!.Location);
        }

        [Fact]
        public void DbInitializer_SeedsData()
        {
            var context = TestDbContextFactory.Create();
            DbInitializer.Initialize(context);

            Assert.True(context.Students.Any());
            Assert.True(context.Instructors.Any());
            Assert.True(context.Departments.Any());
            Assert.True(context.Courses.Any());
            Assert.True(context.Enrollments.Any());

            context.Dispose();
        }

        [Fact]
        public void DbInitializer_DoesNotReseed()
        {
            var context = TestDbContextFactory.Create();
            DbInitializer.Initialize(context);
            var studentCount = context.Students.Count();

            // Call Initialize again - should not add more data
            DbInitializer.Initialize(context);
            Assert.Equal(studentCount, context.Students.Count());

            context.Dispose();
        }
    }
}

